// 講談ライブ字幕（練習モードつき） — served at /subtitles/kodan/
export default "<!doctype html>\n<html lang=\"ja\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>講談ライブ字幕｜練習モードつき</title>\n<style>\n:root{--bg:#f5f1e8;--card:#fff;--ink:#1f1d1a;--sub:#6f6a62;--line:#e0d8c8;--acc:#8f2424;--acc2:#fbeeee;--ok:#2f6f4f;--warn:#9a5a00}\n*{box-sizing:border-box}\nbody{margin:0;font-family:\"Yu Gothic UI\",\"Hiragino Sans\",\"Noto Sans JP\",sans-serif;background:var(--bg);color:var(--ink);line-height:1.6}\nheader{background:#1f1d1a;color:#fff;padding:12px 20px;display:flex;align-items:center;gap:14px;flex-wrap:wrap}\nheader h1{margin:0;font-size:19px}\nheader .sub{font-size:12px;opacity:.7}\nheader .enmoku{margin-left:auto;display:flex;align-items:center;gap:6px;font-size:14px}\nheader select,header button{font:inherit;font-size:14px;border-radius:8px;border:1px solid #555;background:#2b2925;color:#fff;padding:5px 10px}\nmain{max-width:1100px;margin:0 auto;padding:18px 20px 60px}\n.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:18px}\n.step{font:inherit;text-align:left;border:2px solid var(--line);background:#fff;border-radius:14px;padding:12px 16px;cursor:pointer;color:var(--ink)}\n.step .n{display:inline-flex;width:30px;height:30px;border-radius:50%;background:#eee6d6;align-items:center;justify-content:center;font-weight:700;margin-right:8px}\n.step b{font-size:18px}\n.step small{display:block;color:var(--sub);font-size:12px;margin-top:2px}\n.step.active{border-color:var(--acc);background:var(--acc2)}\n.step.active .n{background:var(--acc);color:#fff}\n.step.done .n{background:var(--ok);color:#fff}\n.panel{display:none;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:22px 24px}\n.panel.active{display:block}\n.panel h2{margin:0 0 6px;font-size:22px}\n.lead{font-size:16px;margin:0 0 16px}\n.drop{border:3px dashed var(--line);border-radius:14px;padding:34px 20px;text-align:center;background:#fcfaf5;font-size:18px;cursor:pointer}\n.drop.over{border-color:var(--acc);background:var(--acc2)}\n.drop small{display:block;font-size:13px;color:var(--sub);margin-top:6px}\nbutton{font:inherit;cursor:pointer}\n.btn{border:1px solid var(--line);background:#fff;border-radius:10px;padding:9px 16px;font-size:15px}\n.btn:hover{border-color:#999}\n.big{display:inline-flex;align-items:center;gap:8px;border:none;border-radius:14px;padding:16px 30px;font-size:20px;font-weight:700;background:var(--acc);color:#fff}\n.big.stop{background:#333}\n.big.next{background:var(--ok)}\n.big:disabled{opacity:.4;cursor:default}\n.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.msg{white-space:pre-wrap;font-size:15px;margin:14px 0 0;min-height:1.2em}\n.msg.ok{color:var(--ok)}.msg.warn{color:var(--warn)}\n.status{display:inline-flex;align-items:center;gap:8px;font-size:15px;color:var(--sub)}\n.dot{width:12px;height:12px;border-radius:50%;background:#bbb}\n.dot.on{background:#e53e3e;box-shadow:0 0 0 5px rgba(229,62,62,.25)}\n.summary{background:#f7f3ea;border-radius:10px;padding:12px 16px;font-size:15px;margin-top:14px}\n.prompter{margin-top:16px;border:1px solid #2b2925;border-radius:14px;background:#1f1d1a;color:#f4efe4;padding:14px 22px;height:300px;overflow:hidden;position:relative}\n.prompter .pl{font-size:21px;line-height:1.55;padding:5px 10px;border-radius:8px;opacity:.55;cursor:pointer;transition:all .25s;white-space:normal;word-break:break-word}\n.prompter .pl.prev{opacity:.3}\n.prompter .pl.now{opacity:1;font-size:30px;font-weight:700;background:rgba(255,255,255,.08);border-left:5px solid #e0a43a}\n.prompter .pl:hover{opacity:.85}\n.prompter .end{color:#9a9488;font-size:15px;text-align:center;margin-top:30px}\n.pctl{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:10px;font-size:15px}\n.pctl select{font:inherit;padding:5px 8px;border-radius:8px;border:1px solid var(--line)}\n.pctl .pos{color:var(--sub);font-size:13px;margin-left:auto}\n.compare{border:1px solid var(--line);border-radius:12px;padding:10px 14px;margin-top:12px;font-size:16px;line-height:1.7;background:#fffdf8}\n.compare .lab{font-size:12px;color:var(--sub);display:block}\n.compare mark{background:#ffd9d9;color:#8f2424;border-radius:4px;padding:0 2px}\n.compare mark.ok{background:#d9f0e2;color:#2f6f4f}\n.found{margin-top:18px}\n.found h3{font-size:17px;margin:0 0 8px}\n.found ul{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:8px}\n.found li{border:1px solid var(--line);border-radius:10px;padding:8px 12px;font-size:17px;display:flex;align-items:center;gap:8px;background:#fff}\n.found li .wrong{color:var(--acc);text-decoration:line-through}\n.found li .times{margin-left:auto;font-size:12px;color:var(--sub)}\n.empty{color:var(--sub);font-size:14px}\n#stage{background:#000;color:#fff;border-radius:12px;height:380px;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;padding:18px 26px;margin-top:16px}\n#stage:fullscreen{border-radius:0;height:100vh;padding:4vh 5vw}\n.sub-row{margin-top:.5em}.sub-row.old{opacity:.5}\n.sub-line{line-height:1.3;word-break:break-word}\n.sub-line.wait{opacity:.4}.sub-line.interim{opacity:.55}\n.opts{display:flex;gap:16px;flex-wrap:wrap;align-items:center;font-size:15px;margin-top:14px}\n.opts label{display:inline-flex;align-items:center;gap:5px}\ndetails.more{margin-top:22px;border-top:1px solid var(--line);padding-top:12px}\ndetails.more summary{cursor:pointer;font-weight:700;font-size:15px;color:var(--sub)}\n#log{max-height:260px;overflow:auto;font-size:14px;margin-top:8px}\n#log .item{border-bottom:1px solid #eee;padding:6px 0;display:flex;gap:10px;align-items:flex-start}\n#log .item .txt{flex:1}\n#log .item .fix{font-size:12px;color:var(--ok)}\n#log .item button{font-size:12px;padding:2px 8px;border-radius:8px;border:1px solid var(--line);background:#fff;white-space:nowrap}\n/* 言葉の表 */\n.howto{background:#fbf8f1;border:1px solid var(--line);border-radius:8px;padding:10px 12px;margin:10px 0 8px;font-size:14px;line-height:1.7}\n.howto .bad{color:var(--acc);text-decoration:line-through}\n.tablewrap{max-height:420px;overflow:auto;border:1px solid var(--line);border-radius:8px}\n#glossTable{border-collapse:collapse;width:100%;font-size:13px}\n#glossTable th{position:sticky;top:0;background:#f1ede4;text-align:left;padding:6px;white-space:nowrap;z-index:1}\n#glossTable td{border-top:1px solid #eee;padding:3px 4px}\n#glossTable td input[type=text]{width:100%;min-width:70px;border:1px solid transparent;background:transparent;padding:3px 4px;font:inherit}\n#glossTable td input[type=text]:focus{border-color:#bbb;background:#fff}\n#glossTable tr.off td{opacity:.45}\n#glossTable td.n{color:var(--sub);text-align:right}\n#glossTable td .del{border:none;background:none;color:var(--sub)}\n.chips{display:flex;flex-wrap:wrap;gap:4px;align-items:center;min-width:150px}\n.chip{display:inline-flex;align-items:center;background:#fdecec;border:1px solid #f0c9c9;border-radius:999px;padding:1px 4px 1px 9px;font-size:13px;white-space:nowrap}\n.chip.off{background:#eee;border-color:#ddd;color:#999;text-decoration:line-through}\n.chip button{border:none;background:none;color:#a33;font-size:13px;padding:0 4px}\n.chips .add{border:1px dashed #bbb;background:#fff;border-radius:999px;font-size:12px;padding:1px 9px;color:#666}\n.small{font-size:12px;color:var(--sub)}\nkbd{font:11px Consolas,monospace;border:1px solid #bbb;border-bottom-width:2px;border-radius:4px;padding:0 4px;background:#fafafa}\n@media(max-width:760px){.steps{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<header>\n  <h1>講談ライブ字幕</h1><span class=\"sub\">練習モードつき ・ 日本語 → English・中文</span>\n  <div class=\"enmoku\">演目 <select id=\"enmokuSel\"></select><button id=\"enmokuNew\">＋ 新しい演目</button></div>\n</header>\n<main>\n  <div class=\"steps\">\n    <button class=\"step\" data-step=\"1\"><span class=\"n\">1</span><b>台本を入れる</b><small>Word・PDF・テキスト</small></button>\n    <button class=\"step\" data-step=\"2\"><span class=\"n\">2</span><b>練習する</b><small>台本を読むと、まちがいを自動で見つけます</small></button>\n    <button class=\"step\" data-step=\"3\"><span class=\"n\">3</span><b>本番</b><small>字幕を映します</small></button>\n  </div>\n\n  <!-- ① 台本 -->\n  <section class=\"panel\" id=\"p1\">\n    <h2>① 台本を入れる</h2>\n    <p class=\"lead\">語る演目の台本を入れてください。台本に出てくる言葉を覚えて、字幕のまちがいを減らします。</p>\n    <div class=\"drop\" id=\"drop\">📄 ここに台本ファイルをドラッグ<br>または <b>クリックして選ぶ</b>\n      <small>Word（.docx）・PDF・テキスト　／　台本はこのパソコンの中で読み取ります</small></div>\n    <input type=\"file\" id=\"fileIn\" accept=\".docx,.pdf,.txt,.md\" hidden>\n    <div class=\"row\" style=\"margin-top:10px\"><button class=\"btn\" id=\"pasteBtn\">文章を貼り付けて入れる</button></div>\n    <div id=\"pasteBox\" style=\"display:none;margin-top:8px\"><textarea id=\"pasteText\" rows=\"6\" style=\"width:100%;font:15px/1.6 inherit;padding:8px;border:1px solid var(--line);border-radius:8px\" placeholder=\"台本の文章を貼り付けて「入れる」\"></textarea>\n      <div class=\"row\" style=\"margin-top:6px\"><button class=\"btn\" id=\"pasteGo\">入れる</button><button class=\"btn\" id=\"pasteCancel\">やめる</button></div></div>\n    <div class=\"msg\" id=\"msg1\"></div>\n    <div class=\"summary\" id=\"sum1\" style=\"display:none\"></div>\n    <div class=\"row\" style=\"margin-top:18px\"><button class=\"big next\" id=\"to2\" disabled>次へ：練習する →</button></div>\n  </section>\n\n  <!-- ② 練習 -->\n  <section class=\"panel\" id=\"p2\">\n    <h2>② 練習する</h2>\n    <p class=\"lead\">下に出る台本を、<b>黄色い線の行から声に出して読んでください。</b>字幕が台本とちがったところを、自動で見つけます。<br>\n      <span class=\"small\">全部読まなくても大丈夫です。行をクリックすると、そこから読めます。むずかしい言葉や人の名前が出てくるところだけでも効果があります。</span></p>\n    <div class=\"row\">\n      <button class=\"big\" id=\"practiceBtn\">🎤 練習をはじめる</button>\n      <span class=\"status\"><span class=\"dot\" id=\"dot2\"></span><span id=\"status2\">止まっています</span></span>\n    </div>\n    <div class=\"msg warn\" id=\"msg2\"></div>\n    <div class=\"prompter\" id=\"prompter\"><div class=\"end\">台本を入れると、ここに出ます。</div></div>\n    <div class=\"pctl\">\n      <button class=\"btn\" id=\"pPrev\">▲ 前の行</button>\n      <button class=\"btn\" id=\"pNext\">▼ 次の行</button>\n      <button class=\"btn\" id=\"pTop\">最初から</button>\n      <label>行の送り方\n        <select id=\"pMode\">\n          <option value=\"voice\" selected>声に合わせて進む（おすすめ）</option>\n          <option value=\"slow\">一定の速さ：ゆっくり</option>\n          <option value=\"normal\">一定の速さ：ふつう</option>\n          <option value=\"fast\">一定の速さ：はやい</option>\n          <option value=\"manual\">自分で送る（▼ボタン・↓キー）</option>\n        </select></label>\n      <span class=\"pos\" id=\"pPos\"></span>\n    </div>\n    <div class=\"compare\" id=\"compare\"><span class=\"empty\">読みはじめると、ここに「台本」と「字幕（聞き取った字）」が並んで、ちがう字に色が付きます。</span></div>\n    <div class=\"found\">\n      <h3>見つかったまちがい <span class=\"small\" id=\"foundCount\"></span></h3>\n      <p class=\"small\" style=\"margin:0 0 8px\">チェックが付いたものを登録すると、本番では字幕が自動で台本の字になります。いらないものはチェックを外してください。</p>\n      <ul id=\"foundList\"><li class=\"empty\" style=\"border:none\">まだありません</li></ul>\n      <div class=\"row\" style=\"margin-top:12px\">\n        <button class=\"big next\" id=\"registerBtn\" disabled>✓ チェックしたものを登録する</button>\n        <button class=\"btn\" id=\"to3\">本番へ →</button>\n      </div>\n      <div class=\"msg ok\" id=\"msg2b\"></div>\n    </div>\n  </section>\n\n  <!-- ③ 本番 -->\n  <section class=\"panel\" id=\"p3\">\n    <h2>③ 本番</h2>\n    <p class=\"lead\">「本番をはじめる」を押して語ってください。プロジェクターには「プロジェクター用の画面」を映します。</p>\n    <div class=\"row\">\n      <button class=\"big\" id=\"liveBtn\">🎤 本番をはじめる</button>\n      <button class=\"btn\" id=\"projBtn\">🖥 プロジェクター用の画面</button>\n      <button class=\"btn\" id=\"fsBtn\">全画面 <kbd>F</kbd></button>\n      <button class=\"btn\" id=\"blankBtn\">字幕をかくす <kbd>B</kbd></button>\n      <span class=\"status\"><span class=\"dot\" id=\"dot3\"></span><span id=\"status3\">止まっています</span></span>\n    </div>\n    <div class=\"opts\">\n      <span>映す字幕：</span>\n      <label><input type=\"checkbox\" id=\"show-ja\" checked> 日本語</label>\n      <label><input type=\"checkbox\" id=\"show-en\" checked> English</label>\n      <label><input type=\"checkbox\" id=\"show-zh\"> 中文</label>\n      <label>文字の大きさ <input type=\"range\" id=\"fontSize\" min=\"20\" max=\"90\" value=\"44\"></label>\n      <label>出す数 <select id=\"rows\"><option>1</option><option selected>2</option><option>3</option></select></label>\n    </div>\n    <div class=\"msg warn\" id=\"msg3\"></div>\n    <div id=\"stage\"></div>\n    <details class=\"more\" id=\"logBox\">\n      <summary>字幕の記録（まちがいを見つけたら、その場で登録できます）</summary>\n      <div class=\"row\" style=\"margin-top:8px\"><button class=\"btn\" id=\"saveTxt\">テキストで保存</button><button class=\"btn\" id=\"clearLog\">記録を消す</button></div>\n      <div id=\"log\"></div>\n    </details>\n  </section>\n\n  <details class=\"more\" id=\"glossMore\">\n    <summary>くわしい設定：言葉の表（台本から見つけた言葉と、まちがえて出やすい字）</summary>\n    <div class=\"howto\">\n      音声認識は、ときどき字をまちがえます。たとえば「<b>干鰯</b>」と言ったのに「<span class=\"bad\">星川</span>」と書いてしまう、など。<br>\n      この表があると、字幕に「<span class=\"bad\">星川</span>」が出そうになったとき、台本の「<b>干鰯</b>」に<b>なおして</b>出します。<br>\n      <span class=\"small\">・おかしい候補は × で消し、足りないものは ＋ で足してください。　・「なおす」のチェックを外すと、その言葉はなおしません。<br>\n      ・1文字の候補（例：「男」）は、ほかの意味でもよく使うので、なおす対象にしません。　・英語・中国語の欄に書いた訳語は、翻訳で必ず使います。</span>\n    </div>\n    <div class=\"row\" style=\"margin-bottom:8px\">\n      <button class=\"btn\" id=\"checkBtn\">まちがえて出やすい字をAIで調べる</button>\n      <button class=\"btn\" id=\"fillBtn\">空いている訳語を自動で入れる</button>\n      <button class=\"btn\" id=\"addRow\">＋ 1行追加</button>\n      <input type=\"text\" id=\"glossFilter\" placeholder=\"さがす\" style=\"width:120px;font:inherit;padding:6px;border:1px solid var(--line);border-radius:8px\">\n      <span class=\"small\" id=\"glossCount\"></span>\n      <span style=\"margin-left:auto\" class=\"row\"><button class=\"btn\" id=\"glossExport\">書き出し</button><button class=\"btn\" id=\"glossImport\">読み込み</button><input type=\"file\" id=\"glossFile\" accept=\".tsv,.txt\" hidden></span>\n    </div>\n    <div class=\"msg\" id=\"glossMsg\"></div>\n    <div class=\"tablewrap\">\n      <table id=\"glossTable\"><thead><tr>\n        <th>使う</th><th>台本の言葉</th><th>読み方</th><th>英語では</th><th>中国語では</th><th>なおす</th>\n        <th>まちがえて出やすい字<br><span style=\"font-weight:400;font-size:11px\">これが出たら左の言葉になおします</span></th><th>回数</th><th></th>\n      </tr></thead><tbody></tbody></table>\n    </div>\n    <p class=\"small\">翻訳の準備：<span id=\"trStatus\">まだ</span>　／　授業や複数の言語で話す場合は <a href=\"/subtitles/class/\">授業ライブ字幕</a> を使ってください。</p>\n  </details>\n</main>\n<script>\n'use strict';\n/* =========================================================\n   用語集エンジン（資料の言葉を優先する仕組み）\n   rows: [{on,ja,yomi,en,zh,homo,n}]\n   ========================================================= */\nconst Gloss=(()=>{\n  const kata=s=>String(s||'').replace(/[ぁ-ゖ]/g,c=>String.fromCharCode(c.charCodeAt(0)+0x60));\n  const hira=s=>String(s||'').replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));\n  const yomiKey=s=>kata(String(s||'').normalize('NFKC').replace(/[\\s・･]/g,''));\n  const reEsc=s=>s.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\\\$&');\n  // 英語の照合：大文字小文字・長音記号（ō, ū など）・ハイフンの違いを無視\n  const VAR={a:'aāâáà',e:'eēêéè',i:'iīîíì',o:'oōôóò',u:'uūûúù'};\n  const enPat=w=>[...w.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'')].map(c=>{const l=c.toLowerCase();return VAR[l]?'['+VAR[l]+VAR[l].toUpperCase()+']':/[\\s\\-]/.test(c)?'[\\\\s\\\\-]?':reEsc(c);}).join('');\n  const enRe=w=>new RegExp('(^|[^\\\\p{L}\\\\p{N}])('+enPat(w)+')(?=$|[^\\\\p{L}\\\\p{N}])','giu');\n  const isKana=s=>/^[ぁ-ゖァ-ヺー]+$/.test(s);\n  const active=rows=>(rows||[]).filter(r=>r&&r.on);\n\n  /* ---- 日本語：原稿の用語の「聞き間違い」を用語の表記に直す（辞書なし） ----\n     r.alts = ['公団','講壇'] のような、その用語だけの聞き間違い候補（AIが調べ、人が直せる） */\n  function correctJa(text,rows){\n    const fixes=[],saved=[];\n    const act=active(rows).filter(r=>r.ja);\n    const known=new Set(act.map(r=>r.ja));\n    const protect=(w)=>{saved.push(w);return '\\uE000'+(saved.length-1)+'\\uE001';};\n    // 1) 正しい表記はそのまま守る（長い用語から）\n    for(const r of [...act].sort((a,b)=>b.ja.length-a.ja.length))if(text.includes(r.ja))text=text.split(r.ja).join(protect(r.ja));\n    // 2) 聞き間違い候補を置き換える（長い候補から）\n    const pairs=[];\n    for(const r of act)if(r.homo)for(const a of (r.alts||[]))if(a&&[...a].length>=2&&a!==r.ja&&!known.has(a))pairs.push([a,r.ja]);\n    pairs.sort((x,y)=>y[0].length-x[0].length);\n    for(const [a,to] of pairs){\n      if(!text.includes(a))continue;\n      // かなだけの候補は、前後もかなだと単語の一部の可能性があるので直さない\n      if(isKana(a)){\n        const re=new RegExp('(^|[^\\u3041-\\u30ffー])'+reEsc(a)+'(?=$|[^\\u3041-\\u30ffー])','g');\n        text=text.replace(re,(m,p1)=>{fixes.push({from:a,to});return p1+protect(to);});\n      }else{\n        const n=text.split(a).length-1;for(let i=0;i<n;i++)fixes.push({from:a,to});\n        text=text.split(a).join(protect(to));\n      }\n    }\n    // 3) 読みがかなのまま聞き取られた場合（カタカナの単語ぴったり）\n    for(const r of act.filter(r=>r.homo&&yomiKey(r.yomi).length>=3)){\n      const y=yomiKey(r.yomi);\n      const re=new RegExp('(^|[^ァ-ヺー])'+reEsc(y)+'(?=$|[^ァ-ヺー])','g');\n      text=text.replace(re,(m,p1)=>{fixes.push({from:y,to:r.ja});return p1+protect(r.ja);});\n    }\n    text=text.replace(/\\uE000(\\d+)\\uE001/g,(m,i)=>saved[i]);\n    return {text,fixes};\n  }\n  /* ---- 英語：用語の大文字・つづりをそろえる ---- */\n  function correctEn(text,rows){\n    const fixes=[],saved=[];\n    for(const r of active(rows).filter(r=>r.en).sort((a,b)=>b.en.length-a.en.length)){\n      text=text.replace(enRe(r.en),(m,p,w)=>{if(w!==r.en)fixes.push({from:w,to:r.en});saved.push(r.en);return p+'\\uE000'+(saved.length-1)+'\\uE001';});\n    }\n    text=text.replace(/\\uE000(\\d+)\\uE001/g,(m,i)=>saved[i]);\n    return {text,fixes};\n  }\n  function correct(text,lang,rows){\n    if(lang==='ja')return correctJa(text,rows);\n    if(lang==='en')return correctEn(text,rows);\n    return {text,fixes:[]};\n  }\n  /* ---- 音声認識の候補のうち、用語を多く含むものを選ぶ ---- */\n  function score(text,lang,rows){\n    let s=0;const low=text.toLowerCase();\n    for(const r of active(rows)){const w=r[lang];if(!w||w.length<2)continue;\n      if(lang==='en'?enRe(w).test(text):low.includes(w.toLowerCase()))s+=w.length;}\n    return s;\n  }\n  function pickAlternative(alts,lang,rows){\n    if(!alts.length)return 0;\n    const base=score(alts[0],lang,rows);let best=0,bs=base;\n    alts.forEach((a,i)=>{const v=score(a,lang,rows);if(v>bs){bs=v;best=i;}});\n    return best;\n  }\n  /* ---- 翻訳：用語集の訳語を必ず使う ---- */\n  const plainCache=new Map();\n  function findAll(text,word,lang){\n    if(lang==='en')return enRe(word);\n    return null;\n  }\n  async function translate(text,src,tgt,rows,tr){\n    if(src===tgt)return text;\n    const withTgt=active(rows).filter(r=>r[src]&&r[tgt]);\n    // 訳語のない長い用語の中に、訳語のある短い用語が含まれる場合は、長い用語を丸ごと守る\n    const lc=x=>x.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();\n    const terms=active(rows).filter(r=>r[src]&&(r[tgt]||withTgt.some(o=>o!==r&&o[src].length<r[src].length&&lc(r[src]).includes(lc(o[src])))))\n      .sort((a,b)=>b[src].length-a[src].length);\n    let s=text;const hits=[];\n    for(const r of terms){\n      const token='ZXQ'+hits.length+'QXZ';let count=0;\n      if(src==='en'){const re=findAll(s,r.en,'en');s=s.replace(re,(m,p)=>{count++;return p+token;});}\n      else if(s.includes(r[src])){count=s.split(r[src]).length-1;s=s.split(r[src]).join(token);}\n      if(count)hits.push({token,count,from:r[src],to:r[tgt]||r[src]});\n    }\n    if(!hits.length)return await tr(text,src,tgt);\n    try{\n      let out=await tr(s,src,tgt),ok=true;\n      for(const h of hits){\n        const re=new RegExp(h.token.replace(/(\\d+)/,'\\\\s*$1\\\\s*'),'gi');\n        const n=(out.match(re)||[]).length;if(n!==h.count){ok=false;break;}\n        out=out.replace(re,()=>h.to);\n      }\n      if(ok&&!/ZXQ|QXZ/i.test(out))return out;\n    }catch(e){}\n    // 目印が崩れたときは、普通に訳してから用語の訳を差し替える\n    let plain=await tr(text,src,tgt);\n    for(const h of hits){\n      const key=src+'>'+tgt+':'+h.from;\n      try{\n        if(!plainCache.has(key))plainCache.set(key,(await tr(h.from,src,tgt)).replace(/[。.．]$/,'').trim());\n        const t0=plainCache.get(key);\n        if(t0&&t0!==h.to){\n          if(tgt==='en')plain=plain.replace(new RegExp(reEsc(t0),'gi'),h.to);else plain=plain.split(t0).join(h.to);\n        }\n      }catch(e){}\n    }\n    return plain;\n  }\n  /* ---- 資料から用語を拾う ---- */\n  const EN_STOP=new Set('The This That These Those There Then When Where What Which Who Why How In On At For From With And But Or If As By To Of A An It Its We Our You Your They Their He She His Her I My Me Is Are Was Were Be Not No Yes Please Thank Thanks Today Also Figure Fig Table Page Chapter Section Slide Note Example Q A Mr Ms Dr'.split(' '));\n  const HAN='\\\\p{Script=Han}々〆',KAT='\\\\p{Script=Katakana}ー';\n  function extract(text){\n    text=String(text||'').normalize('NFKC');\n    const found=new Map();\n    const add=(o,boost=0)=>{\n      const key=(o.ja||o.en||o.zh||'').toLowerCase();if(!key)return;\n      const e=found.get(key)||{ja:'',yomi:'',en:'',zh:'',n:0,pattern:false};\n      for(const f of ['ja','yomi','en','zh'])if(o[f]&&!e[f])e[f]=o[f];\n      e.n+=o.count||1;if(boost)e.pattern=true;found.set(key,e);\n    };\n    const kanaRatio=(text.match(/[ぁ-ヿ]/g)||[]).length/Math.max(1,(text.match(/[\\p{Script=Han}ぁ-ヿ]/gu)||[]).length);\n    const zhDoc=kanaRatio<0.08&&/\\p{Script=Han}/u.test(text);\n    // 1) 対訳・読みの書き方：講談（Kodan）／Kodan（講談）／講談（こうだん）／タブ区切り\n    for(const m of text.matchAll(new RegExp(`([${HAN}${KAT}]{2,20})\\\\s*[(]\\\\s*([A-Za-z][A-Za-z0-9 .'’\\\\-]{1,40}?)\\\\s*[)]`,'gu')))\n      add({[zhDoc?'zh':'ja']:m[1],en:m[2].trim()},1);\n    for(const m of text.matchAll(new RegExp(`([A-Z][A-Za-z0-9 .'’\\\\-]{1,40}?)\\\\s*[(]\\\\s*([${HAN}${KAT}]{2,20})\\\\s*[)]`,'gu')))\n      add({[zhDoc?'zh':'ja']:m[2],en:m[1].trim()},1);\n    for(const m of text.matchAll(new RegExp(`([${HAN}]{1,12})\\\\s*[(《]\\\\s*([\\\\p{Script=Hiragana}ー]{2,30})\\\\s*[)》]`,'gu')))\n      add({ja:m[1],yomi:m[2]},1);\n    for(const line of text.split(/\\r?\\n/)){\n      const c=line.split('\\t').map(x=>x.trim());\n      if(c.length>=2&&c[0].length<=20&&c[1].length<=50&&/[\\p{Script=Han}ぁ-ヿ]/u.test(c[0])&&/^[A-Za-z]/.test(c[1]))\n        add({ja:c[0],en:c[1],zh:c[2]&&/\\p{Script=Han}/u.test(c[2])?c[2]:''},1);\n    }\n    // 読みの書き方を取り除いてから候補を拾う\n    const body=text.replace(/[(《][\\p{Script=Hiragana}ー]{2,30}[)》]/gu,'');\n    // 2) 日本語・中国語の用語候補\n    {\n      for(const m of body.matchAll(new RegExp(`[${HAN}${KAT}]{2,16}`,'gu'))){\n        const s=m[0];if(/^ー/.test(s))continue;\n        add(zhDoc?{zh:s}:{ja:s});\n      }\n    }\n    // 3) 英語の固有名詞・略語\n    for(const m of body.matchAll(/\\b(?:[A-Z][a-zA-Z’'\\-]+|[A-Z]{2,}[a-z]?)(?:\\s+(?:of|the|and|de|von|du)\\s+[A-Z][a-zA-Z’'\\-]+|\\s+(?:[A-Z][a-zA-Z’'\\-]+|[A-Z]{2,}))*\\b/g)){\n      let s=m[0].trim();const words=s.split(/\\s+/);\n      while(words.length&&EN_STOP.has(words[0]))words.shift();\n      s=words.join(' ');if(s.length<3||EN_STOP.has(s))continue;\n      if(words.length===1&&s.length<4&&!/^[A-Z]{2,}$/.test(s))continue;\n      add({en:s});\n    }\n    // 「伊賀越」と「伊賀越え」のような、ほぼ同じ候補を1つにまとめる\n    const all=[...found.values()];\n    return all.filter(e=>!e.ja||e.pattern||!all.some(f=>f!==e&&f.ja&&f.ja!==e.ja&&f.ja.startsWith(e.ja)&&(f.n>=e.n||(f.pattern&&f.ja.length-e.ja.length<=2))));\n  }\n  /* ---- 用語集に合流させる ---- */\n  function merge(rows,list){\n    const idx=new Map();rows.forEach(r=>{for(const f of ['ja','en','zh'])if(r[f])idx.set(f+':'+r[f].toLowerCase(),r);});\n    let added=0;\n    for(const e of list){\n      const r=(e.ja&&idx.get('ja:'+e.ja.toLowerCase()))||(e.en&&idx.get('en:'+e.en.toLowerCase()))||(e.zh&&idx.get('zh:'+e.zh.toLowerCase()));\n      if(r){r.n=(r.n||0)+e.n;for(const f of ['ja','yomi','en','zh'])if(e[f]&&!r[f])r[f]=e[f];continue;}\n      const nr={on:e.pattern||e.n>=2,ja:e.ja,yomi:e.yomi?hira(e.yomi):'',en:e.en,zh:e.zh,\n        homo:false,alts:[],n:e.n};\n      rows.push(nr);added++;for(const f of ['ja','en','zh'])if(nr[f])idx.set(f+':'+nr[f].toLowerCase(),nr);\n    }\n    rows.sort((a,b)=>(b.on-a.on)||((b.n||0)-(a.n||0)));\n    return added;\n  }\n  return {kata,hira,yomiKey,correct,correctJa,correctEn,score,pickAlternative,translate,extract,merge};\n})();\n\n/* =========================================================\n   資料の読み取り（PowerPoint / Word / PDF / テキスト）\n   ========================================================= */\nconst Sources=(()=>{\n  async function unzip(buf){\n    const dv=new DataView(buf);let eocd=-1;\n    for(let i=buf.byteLength-22;i>=Math.max(0,buf.byteLength-65557);i--)if(dv.getUint32(i,true)===0x06054b50){eocd=i;break;}\n    if(eocd<0)throw new Error('ファイルが壊れているか、対応していない形式です');\n    const n=dv.getUint16(eocd+10,true);let p=dv.getUint32(eocd+16,true);const files={};\n    for(let k=0;k<n;k++){\n      const method=dv.getUint16(p+10,true),csize=dv.getUint32(p+20,true),nl=dv.getUint16(p+28,true),el=dv.getUint16(p+30,true),cl=dv.getUint16(p+32,true),lho=dv.getUint32(p+42,true);\n      const name=new TextDecoder().decode(new Uint8Array(buf,p+46,nl));files[name]={method,csize,lho};p+=46+nl+el+cl;\n    }\n    return {names:Object.keys(files),async read(name){\n      const f=files[name];if(!f)return '';\n      const start=f.lho+30+dv.getUint16(f.lho+26,true)+dv.getUint16(f.lho+28,true);\n      const data=new Uint8Array(buf,start,f.csize);\n      if(f.method===0)return new TextDecoder().decode(data);\n      const stream=new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'));\n      return await new Response(stream).text();\n    }};\n  }\n  const xml=s=>new DOMParser().parseFromString(s,'application/xml');\n  function paragraphs(doc,pTag,tTag){\n    const out=[];\n    for(const p of doc.getElementsByTagName(pTag)){\n      let s='';\n      const walk=node=>{for(const c of node.childNodes){\n        if(c.nodeType!==1)continue;\n        if(c.nodeName==='w:ruby'){ // Wordのふりがな → 漢字（よみ）\n          const base=[...c.getElementsByTagName('w:rubyBase')].map(b=>[...b.getElementsByTagName('w:t')].map(t=>t.textContent).join('')).join('');\n          const rt=[...c.getElementsByTagName('w:rt')].map(b=>[...b.getElementsByTagName('w:t')].map(t=>t.textContent).join('')).join('');\n          s+=rt?base+'（'+rt+'）':base;continue;\n        }\n        if(c.nodeName===tTag)s+=c.textContent;\n        else if(c.nodeName==='w:tab'||c.nodeName==='a:tab')s+='\\t';\n        else if(c.nodeName===pTag)continue;\n        else walk(c);\n      }};\n      walk(p);if(s.trim())out.push(s);\n    }\n    return out.join('\\n');\n  }\n  async function pptx(buf){\n    const z=await unzip(buf),num=n=>Number((n.match(/(\\d+)\\.xml$/)||[])[1]||0);\n    const slides=z.names.filter(n=>/^ppt\\/slides\\/slide\\d+\\.xml$/.test(n)).sort((a,b)=>num(a)-num(b));\n    const notes=z.names.filter(n=>/^ppt\\/notesSlides\\/notesSlide\\d+\\.xml$/.test(n)).sort((a,b)=>num(a)-num(b));\n    const parts=[];\n    for(const n of slides)parts.push(paragraphs(xml(await z.read(n)),'a:p','a:t'));\n    for(const n of notes)parts.push(paragraphs(xml(await z.read(n)),'a:p','a:t'));\n    return parts.join('\\n');\n  }\n  async function docx(buf){\n    const z=await unzip(buf);\n    return paragraphs(xml(await z.read('word/document.xml')),'w:p','w:t');\n  }\n  const PDFJS='https://cdn.jsdelivr.net/npm/pdfjs-dist@6.2.108/build/';\n  let pdfLib=null;\n  async function pdf(buf){\n    if(!pdfLib){pdfLib=await import(PDFJS+'pdf.min.mjs');pdfLib.GlobalWorkerOptions.workerSrc=PDFJS+'pdf.worker.min.mjs';}\n    const doc=await pdfLib.getDocument({data:new Uint8Array(buf),cMapUrl:PDFJS.replace('build/','cmaps/'),cMapPacked:true}).promise;\n    const out=[];\n    for(let i=1;i<=doc.numPages;i++){\n      const tc=await (await doc.getPage(i)).getTextContent();\n      out.push(tc.items.map(it=>it.str+(it.hasEOL?'\\n':'')).join(''));\n    }\n    return out.join('\\n');\n  }\n  async function read(file){\n    const ext=(file.name.match(/\\.([^.]+)$/)||[])[1]?.toLowerCase()||'';\n    if(ext==='pptx')return pptx(await file.arrayBuffer());\n    if(ext==='docx')return docx(await file.arrayBuffer());\n    if(ext==='pdf')return pdf(await file.arrayBuffer());\n    if(['ppt','doc'].includes(ext))throw new Error('古い形式（.'+ext+'）です。PowerPoint / Word で「名前を付けて保存」→ .'+ext+'x 形式にしてから入れてください');\n    return await file.text();\n  }\n  return {read,unzip,pptx,docx,pdf,PDFJS};\n})();\n\n</script>\n<script>\n'use strict';\nconst $=id=>document.getElementById(id);\nconst store={get(k,d){try{const v=localStorage.getItem('kodanSubs.'+k);return v==null?d:JSON.parse(v);}catch(e){return d;}},set(k,v){try{localStorage.setItem('kodanSubs.'+k,JSON.stringify(v));}catch(e){}}};\nconst API_BASE=location.hostname.endsWith('kyokudominamifuji.com')?'':'https://kyokudominamifuji.com';\nconst SR=window.SpeechRecognition||window.webkitSpeechRecognition;\nconst COLORS={ja:'#ffffff',en:'#ffe066',zh:'#7fe3ff'};\nconst TR={ja:'ja',en:'en',zh:'zh-Hant'};\nfunction msg(id,t,cls){const el=$(id);el.textContent=t||'';el.className='msg'+(cls?' '+cls:'');}\nconst esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\n\n/* ================= 演目（台本と言葉の表） ================= */\nconst E=store.get('enmoku',null)||{cur:'',sets:{}};\nif(E.cur&&!E.sets[E.cur])E.cur=Object.keys(E.sets)[0]||'';\nconst cur=()=>E.sets[E.cur];\nconst rows=()=>cur()?cur().rows:[];\nlet saveT=0;function saveE(){clearTimeout(saveT);saveT=setTimeout(()=>store.set('enmoku',E),250);}\nfunction newSet(name){let n=name,i=2;while(E.sets[n])n=name+'（'+(i++)+'）';E.sets[n]={rows:[],script:'',scriptName:'',registered:0};E.cur=n;saveE();return n;}\nfunction renderEnmoku(){\n  const sel=$('enmokuSel');sel.replaceChildren();\n  const names=Object.keys(E.sets);\n  if(!names.length){const o=document.createElement('option');o.textContent='（まだありません）';o.value='';sel.append(o);}\n  for(const n of names){const o=document.createElement('option');o.value=o.textContent=n;sel.append(o);}\n  sel.value=E.cur;\n}\n$('enmokuSel').onchange=()=>{E.cur=$('enmokuSel').value;saveE();refreshAll();};\n$('enmokuNew').onclick=()=>{const n=(prompt('演目の名前（例：家康の伊賀越え）')||'').trim();if(!n)return;newSet(n);refreshAll();goStep(1);};\n\n/* ================= 手順の切り替え ================= */\nlet step=1;\nfunction goStep(n){\n  if(state.mode)stopRec();\n  step=n;store.set('step',n);\n  document.querySelectorAll('.step').forEach(b=>{const k=+b.dataset.step;b.classList.toggle('active',k===n);\n    b.classList.toggle('done',k===1?!!(cur()&&cur().script):k===2?!!(cur()&&cur().registered):false);});\n  for(const k of [1,2,3])$('p'+k).classList.toggle('active',k===n);\n  if(n===3)render();\n  window.scrollTo({top:0,behavior:'smooth'});\n}\ndocument.querySelectorAll('.step').forEach(b=>b.onclick=()=>goStep(+b.dataset.step));\n$('to2').onclick=()=>goStep(2);$('to3').onclick=()=>goStep(3);\n\n/* ================= ① 台本 ================= */\nasync function addScript(name,text){\n  if(!text||!text.trim()){msg('msg1',name+'：文字を読み取れませんでした（写真やスキャンだけのPDFは読み取れません）。','warn');return;}\n  const base=name.replace(/\\.[^.]+$/,'');\n  if(!cur())newSet(base);\n  else if(cur().script&&cur().scriptName!==name)newSet(base); // 別の台本は別の演目に\n  const set=cur();set.script=text;set.scriptName=name;\n  const added=Gloss.merge(set.rows,Gloss.extract(text));\n  saveE();buildIndex();refreshAll();\n  showSummary(`台本「${name}」（${text.length.toLocaleString()}字）を読み込みました。\\n言葉を ${set.rows.length} 個見つけました。まちがえて出やすい字をAIで調べています…`);\n  $('to2').disabled=false;\n  await checkHomophones(text.slice(0,1500),false);\n}\nfunction showSummary(t){const el=$('sum1');el.style.display='block';el.textContent=t;}\nasync function readFile(f){\n  msg('msg1',f.name+' を読み取っています…');\n  try{const t=await Sources.read(f);msg('msg1','');await addScript(f.name,t);}\n  catch(e){msg('msg1',f.name+'：読み取れませんでした。'+(e.message||e),'warn');}\n}\nconst drop=$('drop');\ndrop.onclick=()=>$('fileIn').click();\n$('fileIn').onchange=e=>{const f=e.target.files[0];e.target.value='';if(f)readFile(f);};\ndrop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('over');});\ndrop.addEventListener('dragleave',()=>drop.classList.remove('over'));\ndrop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('over');const f=e.dataTransfer.files[0];if(f)readFile(f);});\n$('pasteBtn').onclick=()=>{$('pasteBox').style.display='block';$('pasteText').focus();};\n$('pasteCancel').onclick=()=>{$('pasteBox').style.display='none';};\n$('pasteGo').onclick=async()=>{const t=$('pasteText').value;if(!t.trim())return;$('pasteBox').style.display='none';await addScript('貼り付けた台本',t);$('pasteText').value='';};\n\nasync function checkHomophones(context,all){\n  const HAN=/\\p{Script=Han}/u;\n  const targets=rows().filter(r=>r.on&&r.ja&&HAN.test(r.ja)&&r.ja.length<=12&&(all||!r.checked)).slice(0,150);\n  if(!targets.length){afterCheck('');return;}\n  $('checkBtn').disabled=true;let done=0,found=0,failed='';\n  for(let i=0;i<targets.length;i+=30){\n    const batch=targets.slice(i,i+30);\n    msg('glossMsg',`まちがえて出やすい字をAIで調べています… ${done}/${targets.length}語`);\n    try{\n      const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),90000);\n      const r=await fetch(API_BASE+'/subtitles/api/homophones',{method:'POST',headers:{'content-type':'application/json'},signal:ctl.signal,\n        body:JSON.stringify({terms:batch.map(x=>({ja:x.ja,yomi:x.yomi||''})),context:context||''})}).finally(()=>clearTimeout(timer));\n      const d=await r.json();if(!r.ok)throw new Error(d.error||r.status);\n      for(const it of d.items||[]){\n        const row=batch.find(x=>x.ja===it.ja);if(!row)continue;\n        if(it.yomi&&!row.yomi)row.yomi=it.yomi;\n        row.alts=[...new Set([...(row.alts||[]),...(it.confusions||[])])].filter(a=>a&&a!==row.ja);row.checked=true;\n        if(row.alts.some(a=>[...a].length>=2)&&!it.risky){row.homo=true;found++;}\n      }\n    }catch(e){failed=e.name==='AbortError'?'時間切れ':(e.message||String(e));break;}\n    done+=batch.length;saveE();renderGlossTable();\n  }\n  $('checkBtn').disabled=false;\n  afterCheck(failed?`AIのチェックが途中で止まりました（${failed}）。練習モードでまちがいを見つけられるので、このまま進んで大丈夫です。`\n    :`AIが ${found} 個の言葉に「まちがえて出やすい字」を入れました。`);\n}\nfunction afterCheck(t){\n  msg('glossMsg',t);\n  if(cur()&&cur().script){\n    const s=$('sum1').textContent.replace(/\\nまちがえて出やすい字をAIで調べています…$/,'');\n    showSummary(s+(t?'\\n'+t:'')+'\\n\\n次は「② 練習する」です。台本を声に出して読むと、実際に起きるまちがいを自動で見つけます。');\n  }\n}\n\n/* ================= ② 練習：台本と字幕を比べる ================= */\nconst norm=s=>String(s||'').normalize('NFKC')\n  .replace(/[(《][ぁ-ゖー]{1,30}[)》]/g,'')                 // ふりがな（よみ）を取る\n  .replace(/[\\s、。,.!?「」『』()〈〉《》【】…‥・:;\"'“”‘’―—~〜*＊]/g,'');\nconst isHK=c=>/[\\p{Script=Han}\\p{Script=Katakana}ー々〆]/u.test(c||'');\nconst P={S:'',idx:new Map(),occ:[],cursor:0,lines:[],starts:[],line:0};\n// 台本を、読みやすい長さの行に分ける（段落 → 文 → 長い文は読点で）\nfunction splitLines(text){\n  const out=[];\n  for(let para of String(text||'').replace(/\\r/g,'').split(/\\n+/)){\n    para=para.replace(/[ \\t\\u3000]+/g,' ').trim();if(!para)continue;\n    const sents=para.match(/[^。！？!?]+[。！？!?」』）)]*|[^。！？!?]+$/g)||[para];\n    let buf='';\n    for(const s of sents){\n      if((buf+s).length<=38){buf+=s;continue;}\n      if(buf)out.push(buf);buf='';\n      let t=s;\n      while(t.length>38){let c=-1;for(const m of t.slice(0,38).matchAll(/[、，,]/g))c=m.index+1;if(c<12)c=38;out.push(t.slice(0,c));t=t.slice(c);}\n      buf=t;\n    }\n    if(buf)out.push(buf);\n  }\n  return out;\n}\nfunction buildIndex(){\n  P.lines=splitLines(cur()?cur().script:'');P.starts=[];let S='';\n  for(const l of P.lines){P.starts.push(S.length);S+=norm(l);}\n  P.S=S;P.idx=new Map();\n  P.line=Math.min(cur()&&cur().line||0,Math.max(0,P.lines.length-1));P.cursor=P.starts[P.line]||0;\n  renderPrompter();\n  for(let i=0;i<P.S.length-1;i++){const bg=P.S.substr(i,2);let a=P.idx.get(bg);if(!a)P.idx.set(bg,a=[]);a.push(i);}\n  buildOcc();\n}\nfunction buildOcc(){\n  P.occ=[];\n  for(const r of rows())if(r.on&&r.ja&&[...r.ja].length>=2){const w=norm(r.ja);if(!w)continue;let i=0;while((i=P.S.indexOf(w,i))>=0){P.occ.push([i,i+w.length]);i+=w.length;}}\n}\nfunction locate(u){\n  const votes=new Map();\n  for(let k=0;k<u.length-1;k++){\n    const list=P.idx.get(u.substr(k,2));if(!list||list.length>300)continue;\n    for(const q of list){const b=(q-k)>>2;votes.set(b,(votes.get(b)||0)+1+(Math.abs(q-k-P.cursor)<400?0.5:0));}\n  }\n  let best=-1,bv=0;for(const [b,v] of votes)if(v>bv||(v===bv&&Math.abs(b*4-P.cursor)<Math.abs(best*4-P.cursor))){bv=v;best=b;}\n  return bv>=Math.max(2,(u.length-1)*0.25)?Math.max(0,best*4):null;\n}\nfunction align(u,s){ // 字幕 u を台本 s の一部に合わせる（台本の前後は自由）\n  const n=u.length,m=s.length,dp=[],bt=[];\n  for(let i=0;i<=n;i++){dp.push(new Int16Array(m+1));bt.push(new Uint8Array(m+1));}\n  for(let i=1;i<=n;i++){dp[i][0]=-i;bt[i][0]=1;}\n  for(let j=1;j<=m;j++){dp[0][j]=0;bt[0][j]=2;}\n  for(let i=1;i<=n;i++)for(let j=1;j<=m;j++){\n    const d=dp[i-1][j-1]+(u[i-1]===s[j-1]?2:-1),up=dp[i-1][j]-1,lf=dp[i][j-1]-1;\n    if(d>=up&&d>=lf){dp[i][j]=d;bt[i][j]=0;}else if(up>=lf){dp[i][j]=up;bt[i][j]=1;}else{dp[i][j]=lf;bt[i][j]=2;}\n  }\n  let bj=0;for(let j=1;j<=m;j++)if(dp[n][j]>dp[n][bj])bj=j;\n  const ops=[];let i=n,j=bj;\n  while(i>0){\n    const b=bt[i][j];\n    if(b===0){ops.push({a:u[i-1],b:s[j-1],j:j-1});i--;j--;}\n    else if(b===1){ops.push({a:u[i-1],b:'',j:-1});i--;}\n    else{ops.push({a:'',b:s[j-1],j:j-1});j--;}\n  }\n  ops.reverse();\n  // 台本側の飛ばした部分は、最初と最後は含めない\n  while(ops.length&&!ops[0].a)ops.shift();\n  while(ops.length&&!ops[ops.length-1].a)ops.pop();\n  return ops;\n}\nconst found=new Map(); // key -> {rec,ref,count,checked}\nfunction practiceUtterance(raw){\n  const u=norm(raw);if(u.length<3)return;\n  if(!P.S){msg('msg2','先に「① 台本を入れる」で台本を入れてください。','warn');return;}\n  const st=locate(u);\n  if(st==null){showCompare(null,raw);return;}\n  const s0=Math.max(0,st-8),s=P.S.slice(s0,st+Math.ceil(u.length*1.5)+8);\n  const ops=align(u,s);\n  const matched=ops.filter(o=>o.a&&o.a===o.b).length,conf=matched/u.length;\n  const js=ops.filter(o=>o.j>=0);if(js.length&&conf>=0.45){P.cursor=s0+js[js.length-1].j+1;if(pMode()==='voice')setLine(lineOf(P.cursor),false);}\n  showCompare(ops,raw,conf);\n  if(conf<0.45)return;\n  // ちがうところのまとまりを取り出す\n  for(let k=0;k<ops.length;){\n    if(ops[k].a&&ops[k].a===ops[k].b){k++;continue;}\n    let e=k;while(e<ops.length&&!(ops[e].a&&ops[e].a===ops[e].b))e++;\n    const blk=ops.slice(k,e);k=e;\n    const sj=blk.filter(o=>o.j>=0).map(o=>o.j);if(!sj.length)continue;\n    let A1=s0+Math.min(...sj),A2=s0+Math.max(...sj)+1;\n    // 言葉の表の言葉に重なっていれば、その言葉全体に広げる。なければ漢字・カタカナのまとまりに広げる\n    const ov=P.occ.filter(([a,b])=>a<A2&&b>A1);\n    if(ov.length){A1=Math.min(A1,...ov.map(x=>x[0]));A2=Math.max(A2,...ov.map(x=>x[1]));}\n    else{while(A1>0&&isHK(P.S[A1-1]))A1--;while(A2<P.S.length&&isHK(P.S[A2]))A2++;}\n    // 端のひらがな（助詞など）は外す\n    const inOcc=p=>P.occ.some(([a,b])=>p>=a&&p<b),isHira=c=>/[\\u3041-\\u3096]/.test(c||'');\n    while(A2>A1&&isHira(P.S[A2-1])&&!inOcc(A2-1))A2--;\n    while(A1<A2&&isHira(P.S[A1])&&!inOcc(A1))A1++;\n    if(A2<=A1)continue;\n    const ref=P.S.slice(A1,A2);\n    if(!/[\\p{Script=Han}\\p{Script=Katakana}]/u.test(ref)||ref.length>16)continue;\n    let rec='',inside=false;\n    for(const o of ops){\n      if(o.j>=0){const p=s0+o.j;inside=p>=A1&&p<A2;if(inside)rec+=o.a;else if(p>=A2)break;}\n      else if(inside)rec+=o.a;\n    }\n    if(!rec||rec===ref||[...rec].length<2||rec.length>20||ref.includes(rec)||rec.includes(ref))continue;\n    const row=rows().find(r=>r.ja===ref);if(row&&(row.alts||[]).includes(rec))continue;\n    const key=rec+'→'+ref,f=found.get(key);\n    if(f)f.count++;else found.set(key,{rec,ref,count:1,checked:true});\n  }\n  renderFound();\n}\nfunction showCompare(ops,raw,conf){\n  const box=$('compare');\n  if(!ops){box.innerHTML=`<span class=\"lab\">字幕</span>${esc(raw)}<br><span class=\"small\">台本の中に見つかりませんでした（台本にない部分かもしれません）。</span>`;return;}\n  let sh='',rh='';\n  for(const o of ops){\n    if(o.a&&o.a===o.b){sh+=esc(o.b);rh+=esc(o.a);}\n    else{if(o.b)sh+=`<mark class=\"ok\">${esc(o.b)}</mark>`;if(o.a)rh+=`<mark>${esc(o.a)}</mark>`;}\n  }\n  box.innerHTML=`<span class=\"lab\">台本</span>${sh}<span class=\"lab\" style=\"margin-top:6px\">字幕（聞き取った字）</span>${rh}`+\n    (conf<0.45?'<br><span class=\"small\">台本とあまり合わなかったので、まちがい探しには使いませんでした。</span>':'');\n}\nfunction renderFound(){\n  const ul=$('foundList');ul.replaceChildren();\n  const list=[...found.values()];\n  $('foundCount').textContent=list.length?`（${list.length}個）`:'';\n  if(!list.length){const li=document.createElement('li');li.className='empty';li.style.border='none';li.textContent='まだありません';ul.append(li);}\n  for(const f of list){\n    const li=document.createElement('li');const cb=document.createElement('input');cb.type='checkbox';cb.checked=f.checked;cb.onchange=()=>{f.checked=cb.checked;updateRegisterBtn();};\n    li.append(cb);\n    li.insertAdjacentHTML('beforeend',`<span class=\"wrong\">${esc(f.rec)}</span> → <b>${esc(f.ref)}</b><span class=\"times\">${f.count}回</span>`);\n    li.onclick=e=>{if(e.target!==cb){cb.checked=!cb.checked;cb.onchange();}};\n    ul.append(li);\n  }\n  updateRegisterBtn();\n}\nfunction updateRegisterBtn(){$('registerBtn').disabled=![...found.values()].some(f=>f.checked);}\n$('registerBtn').onclick=()=>{\n  let n=0;\n  for(const [key,f] of [...found]){\n    if(!f.checked)continue;\n    let row=rows().find(r=>r.ja===f.ref);\n    if(!row){row={on:true,ja:f.ref,yomi:'',en:'',zh:'',homo:true,alts:[],n:0,checked:true};cur().rows.unshift(row);}\n    row.alts=[...new Set([...(row.alts||[]),f.rec])];row.homo=true;row.on=true;found.delete(key);n++;\n  }\n  cur().registered=(cur().registered||0)+n;saveE();buildOcc();renderFound();renderGlossTable();goStepMarks();\n  msg('msg2b',`${n}個を登録しました。本番では、字幕に出たときに台本の字になおします。続けて練習してもいいですし、「本番へ」に進んでもいいです。`,'ok');\n};\nfunction goStepMarks(){document.querySelectorAll('.step').forEach(b=>{const k=+b.dataset.step;b.classList.toggle('done',k===1?!!(cur()&&cur().script):k===2?!!(cur()&&cur().registered):false);});}\n\n/* ---- 台本の表示（プロンプター） ---- */\nconst pMode=()=>$('pMode').value;\nfunction lineOf(pos){let lo=0,hi=P.starts.length-1;while(lo<hi){const mid=(lo+hi+1)>>1;if(P.starts[mid]<=pos)lo=mid;else hi=mid-1;}\n  // 行の終わりまで読んだら次の行へ\n  const end=lo+1<P.starts.length?P.starts[lo+1]:P.S.length;return pos>=end-1&&lo+1<P.lines.length?lo+1:lo;}\nfunction setLine(n,moveCursor=true){\n  if(!P.lines.length)return;n=Math.max(0,Math.min(P.lines.length-1,n));\n  P.line=n;if(moveCursor)P.cursor=P.starts[n];if(cur()){cur().line=n;saveE();}\n  renderPrompter();scheduleAuto();\n}\nfunction renderPrompter(){\n  const box=$('prompter');\n  if(!P.lines.length){box.innerHTML='<div class=\"end\">台本を入れると、ここに出ます。</div>';$('pPos').textContent='';return;}\n  let h='';const from=Math.max(0,P.line-1),to=Math.min(P.lines.length,P.line+5);\n  for(let i=from;i<to;i++)h+=`<div class=\"pl${i<P.line?' prev':i===P.line?' now':''}\" data-i=\"${i}\">${esc(P.lines[i])}</div>`;\n  if(to>=P.lines.length)h+='<div class=\"end\">― ここで台本はおわりです ―</div>';\n  box.innerHTML=h;\n  box.querySelectorAll('.pl').forEach(el=>el.onclick=()=>setLine(+el.dataset.i));\n  $('pPos').textContent=`${P.line+1} / ${P.lines.length} 行`;\n}\nlet autoT=0;\nfunction scheduleAuto(){\n  clearTimeout(autoT);\n  const cps={slow:4,normal:5.5,fast:7}[pMode()];\n  if(!cps||state.mode!=='practice'||!P.lines.length)return;\n  const len=norm(P.lines[P.line]).length;\n  autoT=setTimeout(()=>{if(P.line<P.lines.length-1)setLine(P.line+1);},Math.max(1500,len/cps*1000));\n}\n// 話している途中でも、聞き取った字から読んでいる行を追いかける\nfunction followInterim(text){\n  if(pMode()!=='voice'||!P.S)return;\n  const u=norm(text);if(u.length<4)return;\n  const st=locate(u);if(st==null||Math.abs(st-P.cursor)>600)return;\n  const ln=lineOf(Math.min(P.S.length-1,st+u.length));if(ln>P.line&&ln<=P.line+2)setLine(ln,false);\n}\n$('pPrev').onclick=()=>setLine(P.line-1);$('pNext').onclick=()=>setLine(P.line+1);$('pTop').onclick=()=>setLine(0);\n$('pMode').onchange=()=>{store.set('pMode',pMode());scheduleAuto();};\n{const pm=store.get('pMode',null);if(pm)$('pMode').value=pm;}\n\n/* ================= 音声認識（練習・本番で共通） ================= */\nconst state={mode:null,rec:null,session:0,committed:new Map(),interims:[],interim:'',blank:false,popup:null,translators:new Map(),log:[],seq:0};\nfunction setStatus(mode,text,on){const n=mode==='practice'?2:3;$('status'+n).textContent=text;$('dot'+n).classList.toggle('on',!!on);}\nfunction cutPoint(t,max){const sl=t.slice(0,max);let c=0,m;const re=/[。！？!?、，,]/g;while((m=re.exec(sl)))c=m.index+1;return c>=max*.4?c:max;}\nfunction commit(t){if(!t||!t.trim())return;if(state.mode==='practice')practiceUtterance(t);else if(state.mode==='live')liveUtterance(t);}\nfunction startRec(mode){\n  if(!SR){msg(mode==='practice'?'msg2':'msg3','このブラウザは音声認識に対応していません。パソコン版の Google Chrome で開いてください。','warn');return false;}\n  const r=new SR(),session=++state.session;state.rec=r;state.mode=mode;state.committed=new Map();state.interims=[];\n  r.lang='ja-JP';r.continuous=true;r.interimResults=true;r.maxAlternatives=mode==='live'?5:1;\n  r.onstart=()=>{if(session===state.session)setStatus(mode,mode==='practice'?'聞いています（台本を読んでください）':'聞いています',true);};\n  r.onresult=e=>{\n    if(session!==state.session)return;\n    const now=performance.now(),list=[];let shown='';\n    for(let i=e.resultIndex;i<e.results.length;i++){\n      const res=e.results[i],txt=res[0].transcript;let c=Math.min(state.committed.get(i)||0,txt.length);\n      if(res.isFinal){\n        let use=txt;\n        if(mode==='live'&&c===0&&res.length>1){const alts=[...res].map(a=>a.transcript);const k=Gloss.pickAlternative(alts,'ja',rows());if(k>0)use=alts[k];}\n        commit(use.slice(c));state.committed.set(i,txt.length);continue;\n      }\n      let rest=txt.slice(c);\n      while(rest.length>40){const cut=cutPoint(rest,40);commit(rest.slice(0,cut));c+=cut;state.committed.set(i,c);rest=rest.slice(cut);}\n      const p=state.interims.find(x=>x.i===i);list.push({i,base:c,text:rest,at:p&&p.text===rest&&p.base===c?p.at:now});shown+=rest;\n    }\n    state.interims=list;state.interim=shown.trim();if(mode==='live')render();else followInterim(state.interim);\n  };\n  r.onerror=e=>{\n    if(session!==state.session)return;\n    const id=mode==='practice'?'msg2':'msg3';\n    if(e.error==='not-allowed'||e.error==='service-not-allowed'){msg(id,'マイクが許可されていません。アドレスバー左のアイコンからマイクを「許可」にしてください。','warn');stopRec();}\n    else if(e.error==='network')msg(id,'音声認識の通信が切れました。自動でつなぎ直します。','warn');\n  };\n  r.onend=()=>{if(session!==state.session)return;flushInterims();if(state.mode)setTimeout(()=>{if(state.mode===mode&&session===state.session){try{startRec(mode);}catch(e){}}},250);};\n  r.start();return true;\n}\nfunction flushInterims(){const m=state.mode;for(const x of state.interims){if(m)commit(x.text);state.committed.set(x.i,x.base+x.text.length);}state.interims=[];state.interim='';}\nsetInterval(()=>{\n  if(!state.mode||!state.interims.length)return;const now=performance.now();let ch=false;\n  for(const x of state.interims)if(x.text&&now-x.at>2000){commit(x.text);state.committed.set(x.i,x.base+x.text.length);x.base+=x.text.length;x.text='';ch=true;}\n  if(ch){state.interims=state.interims.filter(x=>x.text);state.interim=state.interims.map(x=>x.text).join('').trim();if(state.mode==='live')render();}\n},300);\nfunction stopRec(){\n  clearTimeout(autoT);\n  const m=state.mode;flushInterims();state.mode=null;state.session++;try{state.rec&&state.rec.stop();}catch(e){}state.rec=null;\n  $('practiceBtn').textContent='🎤 練習をはじめる';$('practiceBtn').classList.remove('stop');\n  $('liveBtn').textContent='🎤 本番をはじめる';$('liveBtn').classList.remove('stop');\n  setStatus('practice','止まっています');setStatus('live','止まっています');render();\n}\n$('practiceBtn').onclick=()=>{\n  if(state.mode==='practice'){stopRec();return;}\n  if(state.mode)stopRec();\n  if(!cur()||!cur().script){msg('msg2','先に「① 台本を入れる」で台本を入れてください。','warn');return;}\n  msg('msg2','');buildIndex();\n  if(startRec('practice')){$('practiceBtn').textContent='■ 練習をおわる';$('practiceBtn').classList.add('stop');scheduleAuto();}\n};\n\n/* ================= ③ 本番 ================= */\nfunction setTr(t){$('trStatus').textContent=t;}\nasync function ensureTranslator(tgt,gesture){\n  const key='ja>'+tgt;if(state.translators.has(key))return state.translators.get(key);\n  if(!('Translator' in self))return null;\n  const opts={sourceLanguage:'ja',targetLanguage:TR[tgt]};\n  let a;try{a=await Translator.availability(opts);}catch(e){a='unavailable';}\n  if(a==='unavailable'||(a!=='available'&&!gesture))return null;\n  try{setTr('翻訳データを準備中…');const t=await Translator.create({...opts,monitor(m){m.addEventListener('downloadprogress',e=>setTr('翻訳データをダウンロード中 '+Math.round(e.loaded*100)+'%'));}});state.translators.set(key,t);setTr('使えます（パソコンの中で翻訳）');return t;}\n  catch(e){return null;}\n}\nconst withTimeout=(p,ms)=>Promise.race([p,new Promise((_,rej)=>setTimeout(()=>rej(new Error('時間切れ')),ms))]);\nasync function serverTranslate(text,tgt){\n  const glossary=rows().filter(r=>r.on).slice(0,80).map(r=>({ja:r.ja||'',en:r.en||'',zh:r.zh||'',yomi:r.yomi||''}));\n  const r=await fetch(API_BASE+'/subtitles/api/translate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text,src:'ja',targets:[tgt],glossary})});\n  const d=await r.json();if(!r.ok||!d[tgt])throw new Error(d.error||r.status);setTr('サイトのサーバーで翻訳しています');return d[tgt];\n}\nasync function translate(text,a,b){\n  if(a===b)return text;\n  const key='ja>'+b;let t=state.translators.get(key)||await ensureTranslator(b,false);\n  if(t){try{return await withTimeout(t.translate(text),10000);}catch(e){state.translators.delete(key);t=await ensureTranslator(b,false);if(t){try{return await withTimeout(t.translate(text),10000);}catch(e2){}}}}\n  return await serverTranslate(text,b);\n}\nfunction liveUtterance(raw){\n  const g=Gloss.correct(raw.trim(),'ja',rows());if(!g.text)return;\n  const row={id:++state.seq,time:new Date().toISOString(),raw,text:{ja:g.text},fixes:g.fixes,err:{}};\n  state.log.push(row);if(state.log.length>1500)state.log.shift();\n  render();renderLog();\n  (async()=>{\n    for(const k of ['en','zh']){\n      if(!$('show-'+k).checked)continue;\n      try{row.text[k]=await Gloss.translate(row.text.ja,'ja',k,rows(),translate);}catch(e){row.err[k]=e.message||String(e);}\n      render();\n    }\n    renderLog();\n  })();\n}\n$('liveBtn').onclick=async()=>{\n  if(state.mode==='live'){stopRec();return;}\n  if(state.mode)stopRec();\n  msg('msg3','');setTr('準備中…');\n  await Promise.all(['en','zh'].filter(k=>$('show-'+k).checked).map(k=>ensureTranslator(k,true)));\n  if(!('Translator' in self))setTr('このブラウザでは内蔵翻訳が使えないため、サイトのサーバーで翻訳します');\n  if(startRec('live')){$('liveBtn').textContent='■ 本番をおわる';$('liveBtn').classList.add('stop');}\n};\nfunction stageHTML(){\n  const n=+$('rows').value,list=state.log.slice(-n);let h='';\n  list.forEach((r,i)=>{\n    h+=`<div class=\"sub-row${i<list.length-1||state.interim?' old':''}\">`;\n    for(const k of ['ja','en','zh']){\n      if(!$('show-'+k).checked)continue;\n      const t=r.text[k];if(!t&&r.err[k])continue;\n      h+=`<div class=\"sub-line${t?'':' wait'}\" lang=\"${k==='zh'?'zh-Hant-TW':k}\" style=\"color:${COLORS[k]}\">${esc(t||'…')}</div>`;\n    }\n    h+='</div>';\n  });\n  if(state.interim&&state.mode==='live'&&$('show-ja').checked)h+=`<div class=\"sub-row\"><div class=\"sub-line interim\" style=\"color:${COLORS.ja}\">${esc(state.interim)}</div></div>`;\n  return h;\n}\nfunction render(){\n  const html=state.blank?'':stageHTML(),fs=$('fontSize').value+'px',st=$('stage');\n  st.innerHTML=html;st.style.fontSize=st.matches(':fullscreen')?fs:Math.min(+$('fontSize').value,34)+'px';\n  const p=state.popup;if(p&&!p.closed){try{const s=p.document.getElementById('s');s.innerHTML=html;s.style.fontSize=fs;}catch(e){}}\n}\nfunction renderLog(){\n  const box=$('log');box.replaceChildren();\n  for(const r of state.log.slice(-150).reverse()){\n    const d=document.createElement('div');d.className='item';\n    const t=document.createElement('div');t.className='txt';\n    t.innerHTML=`<span class=\"small\">${new Date(r.time).toLocaleTimeString('ja-JP')}</span><br>${esc(r.text.ja)}`+(r.text.en?`<br><span class=\"small\">${esc(r.text.en)}</span>`:'')+(r.text.zh?`<br><span class=\"small\">${esc(r.text.zh)}</span>`:'')+\n      (r.fixes&&r.fixes.length?`<br><span class=\"fix\">なおした字：${r.fixes.map(f=>esc(f.from)+' → '+esc(f.to)).join('、')}</span>`:'');\n    const b=document.createElement('button');b.textContent='まちがいを登録';b.title='この字幕にまちがった字があれば、登録して次から自動でなおします';\n    b.onclick=()=>registerFromLog(r);\n    d.append(t,b);box.append(d);\n  }\n}\nfunction registerFromLog(r){\n  const wrong=(prompt('字幕にまちがって出た字を入れてください。\\n（字幕：'+r.text.ja+'）\\n例：星川')||'').trim();if(!wrong)return;\n  const right=(prompt('正しい字（台本の字）を入れてください。\\n例：干鰯')||'').trim();if(!right||right===wrong)return;\n  if([...wrong].length<2){alert('1文字の字は、ほかの意味でもよく使うので登録できません。前後の字も含めて入れてください。');return;}\n  if(!cur())newSet('演目');\n  let row=rows().find(x=>x.ja===right);\n  if(!row){row={on:true,ja:right,yomi:'',en:'',zh:'',homo:true,alts:[],n:0,checked:true};cur().rows.unshift(row);}\n  row.alts=[...new Set([...(row.alts||[]),wrong])];row.homo=true;row.on=true;cur().registered=(cur().registered||0)+1;\n  saveE();buildOcc();renderGlossTable();msg('msg3',`「${wrong}」→「${right}」を登録しました。次からは自動でなおします。`,'ok');\n}\nfunction openProjector(){\n  const p=window.open('','kodan-subtitles-screen','popup,width=1200,height=700');\n  if(!p){msg('msg3','ポップアップがブロックされました。アドレスバー右のアイコンから許可するか、「全画面」を使ってください。','warn');return;}\n  state.popup=p;p.document.open();\n  p.document.write(`<!doctype html><html><head><meta charset=\"utf-8\"><title>字幕（クリックで全画面）</title><style>\n  html,body{margin:0;height:100%;background:#000;color:#fff;font-family:\"Yu Gothic UI\",\"Hiragino Sans\",\"Noto Sans JP\",\"Microsoft JhengHei\",sans-serif;cursor:pointer;overflow:hidden}\n  #s{position:absolute;inset:0;padding:4vh 5vw;display:flex;flex-direction:column;justify-content:flex-end}\n  .sub-row{margin-top:.5em}.sub-row.old{opacity:.5}.sub-line{line-height:1.3;word-break:break-word}.sub-line.wait{opacity:.4}.sub-line.interim{opacity:.55}\n  </style></head><body><div id=\"s\"></div></body></html>`);\n  p.document.close();\n  p.document.body.addEventListener('click',()=>{const d=p.document;if(!d.fullscreenElement)d.documentElement.requestFullscreen().catch(()=>{});});\n  p.addEventListener('keydown',onKey);render();\n}\n$('projBtn').onclick=openProjector;\n$('fsBtn').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('stage').requestFullscreen().then(render).catch(()=>{});};\ndocument.addEventListener('fullscreenchange',render);\n$('blankBtn').onclick=()=>{state.blank=!state.blank;$('blankBtn').firstChild.textContent=state.blank?'字幕を出す ':'字幕をかくす ';render();};\nfunction onKey(e){\n  const t=e.target;if(t&&/INPUT|TEXTAREA|SELECT/.test(t.tagName))return;if(e.ctrlKey||e.metaKey||e.altKey)return;\n  if(step===2&&(e.key==='ArrowDown'||e.key==='PageDown')){setLine(P.line+1);e.preventDefault();return;}\n  if(step===2&&(e.key==='ArrowUp'||e.key==='PageUp')){setLine(P.line-1);e.preventDefault();return;}\n  const k=e.key.toLowerCase();if(k==='f'&&step===3)$('fsBtn').click();else if(k==='b'&&step===3)$('blankBtn').click();else return;e.preventDefault();\n}\ndocument.addEventListener('keydown',onKey);\nfor(const id of ['show-ja','show-en','show-zh','fontSize','rows'])$(id).addEventListener('input',()=>{savePrefs();render();});\nfunction savePrefs(){store.set('prefs',{ja:$('show-ja').checked,en:$('show-en').checked,zh:$('show-zh').checked,fs:$('fontSize').value,rows:$('rows').value});}\nfunction loadPrefs(){const p=store.get('prefs',null);if(!p)return;$('show-ja').checked=p.ja;$('show-en').checked=p.en;$('show-zh').checked=p.zh;$('fontSize').value=p.fs;$('rows').value=p.rows;}\nfunction download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['﻿'+text],{type:'text/plain'}));a.download=name;document.body.append(a);a.click();setTimeout(()=>a.remove(),800);}\n$('saveTxt').onclick=()=>download('講談字幕_'+(E.cur||'')+'_'+new Date().toISOString().slice(0,10)+'.txt',state.log.map(r=>`[${new Date(r.time).toLocaleTimeString('ja-JP')}]\\n  JA: ${r.text.ja}\\n  EN: ${r.text.en||''}\\n  中: ${r.text.zh||''}`).join('\\n\\n'));\n$('clearLog').onclick=()=>{if(confirm('記録を消しますか？')){state.log=[];renderLog();render();}};\n\n/* ================= 言葉の表 ================= */\nconst COLS=['ja','yomi','en','zh'];\nfunction renderGlossTable(){\n  const tb=$('glossTable').tBodies[0],q=$('glossFilter').value.trim().toLowerCase(),list=rows();tb.replaceChildren();let shown=0;\n  list.forEach((r,i)=>{\n    if(q&&!COLS.some(f=>(r[f]||'').toLowerCase().includes(q))&&!(r.alts||[]).some(a=>a.includes(q)))return;\n    if(++shown>500)return;\n    const tr=document.createElement('tr');tr.classList.toggle('off',!r.on);\n    const cb=(f,title)=>{const td=document.createElement('td');td.style.textAlign='center';const c=document.createElement('input');c.type='checkbox';c.checked=!!r[f];c.title=title;\n      c.onchange=()=>{r[f]=c.checked;tr.classList.toggle('off',!r.on);saveE();buildOcc();renderCount();};td.append(c);return td;};\n    tr.append(cb('on','この言葉を使う'));\n    for(const f of COLS){const td=document.createElement('td');const inp=document.createElement('input');inp.type='text';inp.value=r[f]||'';inp.oninput=()=>{r[f]=inp.value.trim();saveE();if(f==='ja')buildOcc();};td.append(inp);tr.append(td);}\n    tr.append(cb('homo','チェックを外すと、この言葉はなおしません'));\n    const td=document.createElement('td');const box=document.createElement('div');box.className='chips';\n    const draw=()=>{box.replaceChildren();\n      for(const a of (r.alts||[])){const c=document.createElement('span');c.className='chip'+([...a].length<2?' off':'');c.textContent=a;if([...a].length<2)c.title='1文字なので、なおす対象にしません';\n        const x=document.createElement('button');x.textContent='×';x.title='「'+a+'」を消す';x.onclick=()=>{r.alts=r.alts.filter(v=>v!==a);saveE();draw();renderCount();};c.append(x);box.append(c);}\n      const add=document.createElement('button');add.className='add';add.textContent='＋';add.title='まちがえて出やすい字を足す';\n      add.onclick=()=>{const v=(prompt('「'+(r.ja||'この言葉')+'」と言ったとき、まちがえて出やすい字を入れてください（例：星川）')||'').trim();if(!v)return;\n        r.alts=[...new Set([...(r.alts||[]),...v.split(/[、,，\\s]+/).filter(Boolean)])].filter(a=>a!==r.ja);r.homo=true;saveE();draw();renderCount();};\n      box.append(add);};\n    draw();td.append(box);tr.append(td);\n    const n=document.createElement('td');n.className='n';n.textContent=r.n||'';tr.append(n);\n    const dl=document.createElement('td');const b=document.createElement('button');b.className='del';b.textContent='✕';b.title='この行を消す';b.onclick=()=>{list.splice(i,1);saveE();buildOcc();renderGlossTable();};dl.append(b);tr.append(dl);\n    tb.append(tr);\n  });\n  renderCount();\n}\nfunction renderCount(){const l=rows();$('glossCount').textContent=`${l.length}語（なおす ${l.filter(r=>r.on&&r.homo&&(r.alts||[]).some(a=>[...a].length>=2)).length}）`;}\n$('glossFilter').oninput=renderGlossTable;\n$('addRow').onclick=()=>{if(!cur())newSet('演目');cur().rows.unshift({on:true,ja:'',yomi:'',en:'',zh:'',homo:true,alts:[],n:0});saveE();$('glossFilter').value='';renderGlossTable();$('glossTable').tBodies[0].querySelector('input[type=text]')?.focus();};\n$('checkBtn').onclick=()=>checkHomophones((cur()&&cur().script||'').slice(0,1500),true);\n$('fillBtn').onclick=async()=>{\n  $('fillBtn').disabled=true;let n=0;const list=rows().filter(r=>r.on&&r.ja);\n  await Promise.all(['en','zh'].map(k=>ensureTranslator(k,true)));\n  for(const [i,r] of list.entries()){if(i%5===0)msg('glossMsg',`訳語を入れています… ${i}/${list.length}`);\n    for(const k of ['en','zh'])if(!r[k]){try{r[k]=(await translate(r.ja,'ja',k)).replace(/[。.．]$/,'').trim();n++;}catch(e){}}}\n  saveE();renderGlossTable();$('fillBtn').disabled=false;msg('glossMsg',`${n}か所に訳語を入れました。英語・中国語の欄を、使いたい訳語に直してください（ここの訳語が字幕で必ず使われます）。`);\n};\n$('glossExport').onclick=()=>download('講談の言葉_'+(E.cur||'')+'.tsv',['使う\\t日本語\\tよみ\\tEnglish\\t中文\\t直す\\t聞き間違い',...rows().map(r=>[r.on?1:0,r.ja,r.yomi,r.en,r.zh,r.homo?1:0,(r.alts||[]).join('、')].map(x=>String(x??'').replace(/[\\t\\r\\n]/g,' ')).join('\\t'))].join('\\r\\n'));\n$('glossImport').onclick=()=>$('glossFile').click();\n$('glossFile').onchange=async e=>{\n  const f=e.target.files[0];e.target.value='';if(!f)return;if(!cur())newSet(f.name.replace(/\\.[^.]+$/,''));\n  let n=0;for(const line of (await f.text()).replace(/^﻿/,'').split(/\\r?\\n/)){\n    const c=line.split('\\t').map(x=>x.trim());if(!line.trim()||c[1]==='日本語')continue;\n    const r=/^[01]$/.test(c[0])?{on:c[0]==='1',ja:c[1],yomi:c[2]||'',en:c[3]||'',zh:c[4]||'',homo:c[5]==='1',alts:(c[6]||'').split(/[、,，]/).map(x=>x.trim()).filter(Boolean),n:0}:{on:true,ja:c[0],yomi:'',en:c[1]||'',zh:c[2]||'',homo:false,alts:[],n:0};\n    if(!r.ja)continue;const ex=rows().find(x=>x.ja===r.ja);\n    if(ex){ex.alts=[...new Set([...(ex.alts||[]),...r.alts])];for(const k of ['yomi','en','zh'])if(r[k])ex[k]=r[k];if(r.homo)ex.homo=true;}else cur().rows.push(r);n++;\n  }\n  saveE();buildOcc();renderGlossTable();msg('glossMsg',n+'行を読み込みました。');\n};\n\n/* ================= はじめに ================= */\nfunction refreshAll(){\n  renderEnmoku();buildIndex();renderGlossTable();found.clear();renderFound();\n  const c=cur();\n  if(c&&c.script){showSummary(`台本「${c.scriptName}」（${c.script.length.toLocaleString()}字）を入れてあります。言葉：${c.rows.length}個。\\n別の台本を入れると、新しい演目として追加します。`);$('to2').disabled=false;}\n  else{$('sum1').style.display='none';$('to2').disabled=true;}\n  goStepMarks();\n}\nloadPrefs();refreshAll();\ngoStep(cur()&&cur().script?Math.min(store.get('step',2),3):1);\nif(!SR)msg('msg1','このブラウザは音声認識に対応していません。パソコン版の Google Chrome で開いてください。','warn');\n</script>\n</body>\n</html>\n";
